    var md = videoDs.metadata;
    var vlenClass = (M && M.H5T_class_t && M.H5T_class_t.H5T_VLEN) ? M.H5T_class_t.H5T_VLEN.value : 9;
    var isVlen = !!(md && (md.vlen === true || md.type === vlenClass));
